parties.query:
PREFIX a: <https://data.oireachtas.ie/ontology#>
PREFIX m: <https://data.oireachtas.ie/ontology/members#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
SELECT ?term ?number ?party ?label ?type WHERE {
 GRAPH <https://data.oireachtas.ie/graph/houses> {?term a a:DailTerm; a:termNo ?number . VALUES ?number {12 13}}
 GRAPH <https://data.oireachtas.ie/graph/parties> {?party m:activeDuringTerm ?term; a ?type . VALUES ?type {m:ParliamentaryParty m:ParliamentaryGroup} OPTIONAL {?party skos:prefLabel ?label FILTER(LANG(?label)="en")}}
} ORDER BY ?number ?party ?label

holdings.query:
PREFIX a: <https://data.oireachtas.ie/ontology#>
PREFIX m: <https://data.oireachtas.ie/ontology/members#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
SELECT ?g ?member ?name ?office ?label ?holding ?range ?start ?end WHERE {
 GRAPH <https://data.oireachtas.ie/graph/offices> {?office a m:NamedOffice; skos:prefLabel ?label . VALUES ?label {"Minister for Finance"@en "Tánaiste"@en "Taoiseach"@en}}
 GRAPH ?g {?member a a:Member; foaf:name ?name; m:hasOfficeHolding ?holding . ?holding a m:OfficeHolding; m:heldOffice ?office .
 OPTIONAL {?holding m:hasMembershipDateRange ?range . OPTIONAL {?range m:StartDate ?start} OPTIONAL {?range m:EndDate ?end}}}
 FILTER(STRSTARTS(STR(?g),"https://data.oireachtas.ie/graph/member/"))
} ORDER BY ?office ?member ?holding ?start ?end

representation.query:
PREFIX a: <https://data.oireachtas.ie/ontology#>
PREFIX m: <https://data.oireachtas.ie/ontology/members#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
SELECT ?g ?member ?name ?membership ?term ?number ?constituency ?label ?range ?start ?end ?episode ?party ?affiliation ?affiliationLabel ?prange ?ps ?pe WHERE {
 GRAPH <https://data.oireachtas.ie/graph/houses> {?term a a:DailTerm; a:termNo ?number . VALUES ?number {30 33 34}}
 GRAPH <https://data.oireachtas.ie/graph/constituencies> {?constituency a m:DailConstituency; m:constituencyInHouseTerm ?term; skos:prefLabel ?label . VALUES ?label {"Dublin Central"@en "Dublin West"@en "Wicklow"@en}}
 GRAPH ?g {?member a a:Member; foaf:name ?name; m:hasMembersMembership ?membership . ?membership a m:DailMembership; m:inHouseTerm ?term; m:isRepresentativeFrom ?constituency .
 OPTIONAL {?membership m:hasMembershipDateRange ?range . OPTIONAL {?range m:StartDate ?start} OPTIONAL {?range m:EndDate ?end}}}
 FILTER(STRSTARTS(STR(?g),"https://data.oireachtas.ie/graph/member/"))
 OPTIONAL {GRAPH ?g {?member m:hasMembersMembership ?episode . ?episode a m:PartyMembership; m:inOireachtasMembership ?membership; m:isPartyMembershipOf ?party .
 OPTIONAL {?episode m:hasMembershipDateRange ?prange . OPTIONAL {?prange m:StartDate ?ps} OPTIONAL {?prange m:EndDate ?pe}}}
 GRAPH <https://data.oireachtas.ie/graph/parties> {?party a m:ParliamentaryParty; m:activeDuringTerm ?term}
 GRAPH <https://data.oireachtas.ie/graph/political-affiliations/identities> {?party m:hasPoliticalAffiliationIdentity ?affiliation . ?affiliation skos:prefLabel ?affiliationLabel FILTER(LANG(?affiliationLabel)="en")}}
} ORDER BY ?number ?member ?membership ?episode ?ps ?pe
